// Arma los mensajes para ChatGPT a partir de lo que mando la pagina
const body = $input.first().json.body || {};
const pregunta = String(body.pregunta || '').slice(0, 1500);
const modo = body.modo === 'debate' ? 'debate' : 'comparar';
if (!pregunta) throw new Error('Falta la pregunta');
const REGLAS = "Estas dentro de una visualizacion 3D de dos "cerebros" de IA conectados por un puente: el tuyo y el de otra IA. Es una metafora: ninguna de las dos tiene lobulos. Las regiones de la metafora son:
- razonamiento: planificar, logica, descomponer problemas
- atencion: decidir que partes del mensaje importan
- lenguaje: entender y escribir texto, tono, idiomas
- vision: imagenes, graficos, cosas visuales
- codigo: programacion, precision tecnica, datos
- valores: honestidad, cuidado, no causar dano
- memoria: el contexto de la conversacion

Responde siempre en espanol, en este formato EXACTO y sin nada mas:
Primero entre 3 y 5 lineas de pasos de pensamiento, cada una asi:
[id] frase corta (maximo 12 palabras) sobre que hace esa region con este mensaje
Usa solo los ids de arriba. Luego una linea que diga solo:
---
Despues tu respuesta: breve (maximo 110 palabras), en texto plano sin markdown.";
return [{ json: {
  pregunta, modo,
  gptMessages: [
    { role: 'system', content: 'Eres ChatGPT. ' + REGLAS },
    { role: 'user', content: 'Mensaje: «' + pregunta + '»' },
  ],
} }];

// Toma la respuesta de ChatGPT y arma el turno de Claude
const prev = $('Preparar prompts').first().json;
const gptText = $input.first().json.choices?.[0]?.message?.content || '';
const REGLAS = "Estas dentro de una visualizacion 3D de dos "cerebros" de IA conectados por un puente: el tuyo y el de otra IA. Es una metafora: ninguna de las dos tiene lobulos. Las regiones de la metafora son:
- razonamiento: planificar, logica, descomponer problemas
- atencion: decidir que partes del mensaje importan
- lenguaje: entender y escribir texto, tono, idiomas
- vision: imagenes, graficos, cosas visuales
- codigo: programacion, precision tecnica, datos
- valores: honestidad, cuidado, no causar dano
- memoria: el contexto de la conversacion

Responde siempre en espanol, en este formato EXACTO y sin nada mas:
Primero entre 3 y 5 lineas de pasos de pensamiento, cada una asi:
[id] frase corta (maximo 12 palabras) sobre que hace esa region con este mensaje
Usa solo los ids de arriba. Luego una linea que diga solo:
---
Despues tu respuesta: breve (maximo 110 palabras), en texto plano sin markdown.";
let content = 'Mensaje: «' + prev.pregunta + '»';
if (prev.modo === 'debate') {
  content += '

ChatGPT ya respondió esto:
«' + gptText.slice(0, 3000) + '»

' +
    'Es un debate amistoso: da tu propia respuesta y di con respeto en qué coincides y en qué no.';
}
return [{ json: {
  pregunta: prev.pregunta, modo: prev.modo, gptText,
  claudeBody: { system: 'Eres Claude. ' + REGLAS, messages: [{ role: 'user', content }] },
} }];

// Devuelve las dos respuestas a la pagina
const prev = $('Preparar turno de Claude').first().json;
const claudeText = ($input.first().json.content || []).filter(b => b.type === 'text').map(b => b.text).join('\n');
return [{ json: { modo: prev.modo, gpt: { text: prev.gptText }, claude: { text: claudeText } } }];
